class Solution:
    def findValidPair(self, s: str) -> str:
        count = [0] * 10
        for ch in s:
            count[ord(ch) - ord('0')] += 1

        for i in range(len(s) - 1):
            d1 = ord(s[i]) - ord('0')
            d2 = ord(s[i + 1]) - ord('0')
            if d1 == d2:
                continue
            if count[d1] == d1 and count[d2] == d2:
                return s[i:i + 2]

        return ""

