class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        index = 0
        for row_index, row in enumerate(grid):
            if row_index % 2 == 0:
                col_range = range(len(row))
            else:
                col_range = range(len(row) - 1, -1, -1)
            for col in col_range:
                if index % 2 == 0:
                    result.append(grid[row_index][col])
                index += 1
        return result

