class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        count = {}

        for i in range(0, n - k + 1):
            for value in set(nums[i:i + k]):
                count[value] = count.get(value, 0) + 1

        answer = -1
        for value, times in count.items():
            if times == 1 and value > answer:
                answer = value

        return answer

