class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)

        groups = {}
        for i, v in enumerate(nums):
            groups.setdefault(v, []).append(i)

        ans = [-1] * n

        for _, idxs in groups.items():
            k = len(idxs)
            if k < 2:
                continue

            for pos in range(k):
                curr = idxs[pos]
                nxt = idxs[(pos + 1) % k]
                prv = idxs[(pos - 1) % k]

                d_next = (nxt - curr) % n
                d_prev = (curr - prv) % n

                dist_next = min(d_next, n - d_next)
                dist_prev = min(d_prev, n - d_prev)

                ans[curr] = min(dist_next, dist_prev)

        return [ans[q] for q in queries]

