class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        code = [ord(ch) - ord('a') for ch in s]

        dist = [[0] * 26 for _ in range(26)]
        for i in range(26):
            di = dist[i]
            for j in range(26):
                diff = abs(i - j)
                di[j] = min(diff, 26 - diff)

        same_cost = [[0] * 26 for _ in range(26)]
        for i in range(26):
            for j in range(26):
                di, dj = dist[i], dist[j]
                best = 10 ** 9
                for y in range(26):
                    val = di[y] + dj[y]
                    if val < best:
                        best = val
                same_cost[i][j] = best

        f = [[None for _ in range(n)] for _ in range(n)]
        for i in range(n):
            f[i][i] = [1] * (k + 1)

        for length in range(2, n + 1):
            for l in range(0, n - length + 1):
                r = l + length - 1
                arr = [0] * (k + 1)

                skip_left = f[l + 1][r]
                skip_right = f[l][r - 1]

                if l + 1 <= r - 1:
                    inner = f[l + 1][r - 1]
                else:
                    inner = [0] * (k + 1)

                cost = same_cost[code[l]][code[r]]
                for kk in range(k + 1):
                    best = skip_left[kk]
                    if skip_right[kk] > best:
                        best = skip_right[kk]
                    if kk >= cost:
                        cand = inner[kk - cost] + 2
                        if cand > best:
                            best = cand
                    arr[kk] = best

                f[l][r] = arr

        return f[0][n - 1][k]

