class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n = len(skill)
        m = len(mana)

        prev_finish = [0] * n  # finish time at each wizard for previous potion

        for j in range(m):
            mj = mana[j]
            ps = [0] * (n + 1)
            cur = 0
            for i in range(n):
                cur += skill[i] * mj
                ps[i + 1] = cur

            if j == 0:
                s = 0
            else:
                s = prev_finish[0] - ps[0]
                for i in range(1, n):
                    val = prev_finish[i] - ps[i]
                    if val > s:
                        s = val

            f = [0] * n
            for i in range(n):
                f[i] = s + ps[i + 1]
            prev_finish = f

        return prev_finish[-1]

