class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        pref = [0] * (n + 1)
        for i, x in enumerate(nums, start=1):
            pref[i] = pref[i - 1] + x

        NEG = float('-inf')
        prev = [0] * (n + 1)  # dp[0]

        for _ in range(k):
            curr = [NEG] * (n + 1)
            ptr = -1
            max_val = NEG  # max of prev[l] - pref[l] for l <= i - m

            for i in range(n + 1):
                limit = i - m
                if limit >= 0:
                    while ptr < limit:
                        ptr += 1
                        val = prev[ptr] - pref[ptr]
                        if val > max_val:
                            max_val = val

                skip = curr[i - 1] if i > 0 else NEG
                option = pref[i] + max_val
                curr[i] = skip if skip >= option else option

            prev = curr

        return prev[n]

