def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it)); X = int(next(it))
    items = [[] for _ in range(4)]  # 1..3
    for _ in range(N):
        v = int(next(it)); a = int(next(it)); c = int(next(it))
        items[v].append((a, c))

    NEG = -10**18
    pref = []
    for v in (1, 2, 3):
        dp = [NEG] * (X + 1)
        dp[0] = 0
        for a, c in items[v]:
            # 0/1 knapsack over calorie capacity
            for w in range(X, c - 1, -1):
                prev = dp[w - c]
                if prev != NEG:
                    val = prev + a
                    if val > dp[w]:
                        dp[w] = val
        # p[k] = max units achievable with total calories <= k
        p = [0] * (X + 1)
        cur = 0  # empty subset gives 0 units
        for k in range(1, X + 1):
            if dp[k] > cur:
                cur = dp[k]
            p[k] = cur
        pref.append(p)

    def cost(v, t):
        # smallest calorie budget k such that v can reach at least t units
        p = pref[v - 1]
        if t <= 0:
            return 0
        if t > p[X]:
            return X + 1
        return bisect.bisect_left(p, t)

    def feasible(t):
        return cost(1, t) + cost(2, t) + cost(3, t) <= X

    lo = 0
    hi = min(pref[0][X], pref[1][X], pref[2][X])
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    print(lo)

