class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        odd = (n + 1) // 2
        even = n // 2
        m = n // 2

        if n % 2 == 0:
            total = 2 * fact[m] * fact[m]
        else:
            total = fact[m + 1] * fact[m]

        if k > total:
            return []

        used = [False] * (n + 1)
        res = []
        used_odd = 0
        used_even = 0
        last = -1  # 1 odd, 0 even, -1 none

        for i in range(n):
            chosen = None

            for x in range(1, n + 1):
                if used[x]:
                    continue

                q = x & 1  # 1 if odd, 0 if even
                if i > 0 and q == last:
                    continue

                # Count odd positions among j = i+1 ... n-1
                r_odd = 0
                for j in range(i + 1, n):
                    parity_j = q ^ ((j - i) & 1)
                    if parity_j == 1:
                        r_odd += 1

                rem_odd = odd - (used_odd + (1 if q == 1 else 0))
                rem_even = even - (used_even + (0 if q == 1 else 1))

                if rem_odd != r_odd:
                    continue

                count = fact[rem_odd] * fact[rem_even]
                if k > count:
                    k -= count
                    continue

                chosen = x
                break

            if chosen is None:
                return []

            q = chosen & 1
            used[chosen] = True
            if q:
                used_odd += 1
            else:
                used_even += 1
            last = q
            res.append(chosen)

        return res

class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7
        N = m * n

        fact = [1] * (N + 1)
        for i in range(1, N + 1):
            fact[i] = fact[i - 1] * i % MOD

        invfact = [1] * (N + 1)
        invfact[N] = pow(fact[N], MOD - 2, MOD)
        for i in range(N, 0, -1):
            invfact[i - 1] = invfact[i] * i % MOD

        def comb(a: int, b: int) -> int:
            if b < 0 or b > a:
                return 0
            return fact[a] * invfact[b] % MOD * invfact[a - b] % MOD

        inv6 = pow(6, MOD - 2, MOD)

        def sum_dist_range(L: int) -> int:
            L %= MOD
            return L * ((L * L - 1) % MOD) % MOD * inv6 % MOD

        total_pair_distance = (
            (n % MOD) * (n % MOD) % MOD * sum_dist_range(m)
            + (m % MOD) * (m % MOD) % MOD * sum_dist_range(n)
        ) % MOD

        return total_pair_distance * comb(N - 2, k - 2) % MOD
